int yam_ioctl(struct net_device *dev, struct ifreq *ifr, int cmd)
{
    void __user *user_data = ifr->ifr_data;
    struct yam_dev *yam = netdev_priv(dev);
    int ret = 0;

    if (!capable(CAP_NET_ADMIN))
        return -EPERM;

    if (netif_running(dev)) {
        switch (cmd) {
        case YAMIOCGBITRATE:
        case YAMIOCGBAUDRATE:
        case YAMIOCGETIRQ:
            break;
        default:
            return -EBUSY;
        }
    }

    switch (cmd) {
    case YAMIOCSEBITRATE: {
        u32 bitrate;
        if (copy_from_user(&bitrate, user_data, sizeof(u32)))
            return -EFAULT;
        if (bitrate < 1 || bitrate > MAX_BITRATE)
            return -EINVAL;
        yam->bitrate = bitrate;
        break;
    }
    case YAMIOCSEBAUDRATE: {
        u32 baudrate;
        if (copy_from_user(&baudrate, user_data, sizeof(u32)))
            return -EFAULT;
        if (baudrate < 1 || baudrate > MAX_BAUDRATE)
            return -EINVAL;
        yam->baudrate = baudrate;
        break;
    }
    case YAMIOCSEIRQ: {
        u32 irq;
        if (copy_from_user(&irq, user_data, sizeof(u32)))
            return -EFAULT;
        if (!irq || irq > MAX_IRQ)
            return -EINVAL;
        yam->irq = irq;
        break;
    }
    case YAMIOCGBITRATE:
        if (copy_to_user(user_data, &yam->bitrate, sizeof(u32)))
            return -EFAULT;
        break;
    case YAMIOCGBAUDRATE:
        if (copy_to_user(user_data, &yam->baudrate, sizeof(u32)))
            return -EFAULT;
        break;
    case YAMIOCGETIRQ:
        if (copy_to_user(user_data, &yam->irq, sizeof(u32)))
            return -EFAULT;
        break;
    default:
        ret = -EINVAL;
        break;
    }

    return ret;
}

#include <linux/netdevice.h>
#include <linux/if.h>
#include <linux/uaccess.h>

int yam_ioctl(struct net_device *dev, struct ifreq *ifr, int cmd)
{
    int err = 0;
    void __user *user_data = ifr->ifr_data;
    struct yam_dev *yam_dev = netdev_priv(dev);

    if (!netif_device_present(dev))
        return -ENODEV;

    if (netif_running(dev)) {
        if (cmd == YAM_SET_BITRATE || cmd == YAM_SET_BAUDRATE || cmd == YAM_SET_IRQ) {
            return -EBUSY;
        }
    }

    switch (cmd) {
    case YAM_GET_BITRATE: {
        unsigned int bitrate = yam_dev->bitrate;
        if (copy_to_user(user_data, &bitrate, sizeof(bitrate)))
            return -EFAULT;
        break;
    }
    case YAM_SET_BITRATE: {
        unsigned int new_bitrate;
        if (copy_from_user(&new_bitrate, user_data, sizeof(new_bitrate)))
            return -EFAULT;
        if (new_bitrate < YAM_MIN_BITRATE || new_bitrate > YAM_MAX_BITRATE)
            return -EINVAL;
        yam_dev->bitrate = new_bitrate;
        break;
    }
    case YAM_GET_BAUDRATE: {
        unsigned int baudrate = yam_dev->baudrate;
        if (copy_to_user(user_data, &baudrate, sizeof(baudrate)))
            return -EFAULT;
        break;
    }
    case YAM_SET_BAUDRATE: {
        unsigned int new_baudrate;
        if (copy_from_user(&new_baudrate, user_data, sizeof(new_baudrate)))
            return -EFAULT;
        if (new_baudrate < YAM_MIN_BAUDRATE || new_baudrate > YAM_MAX_BAUDRATE)
            return -EINVAL;
        yam_dev->baudrate = new_baudrate;
        break;
    }
    case YAM_GET_IRQ: {
        int irq = yam_dev->irq;
        if (copy_to_user(user_data, &irq, sizeof(irq)))
            return -EFAULT;
        break;
    }
    case YAM_SET_IRQ: {
        int new_irq;
        if (copy_from_user(&new_irq, user_data, sizeof(new_irq)))
            return -EFAULT;
        if (new_irq < 0 || new_irq >= NR_IRQS)
            return -EINVAL;
        yam_dev->irq = new_irq;
        break;
    }
    default:
        return -EINVAL;
    }

    return err;
}

int yam_ioctl(struct net_device *dev, struct ifreq *ifr, int cmd)
{
    int err = 0;
    void __user *user_data = ifr->ifr_data;

    if (!netif_running(dev)) {
        return -EINVAL;
    }

    if (cmd == SIOCGETBITRATE) {
        unsigned int bitrate;
        if (copy_from_user(&bitrate, user_data, sizeof(bitrate))) {
            return -EFAULT;
        }

        /* Example logic for getting bitrate */
        err = get_bitrate(dev, &bitrate);
        if (err < 0) {
            return err;
        }

        if (copy_to_user(user_data, &bitrate, sizeof(bitrate))) {
            return -EFAULT;
        }

        return 0;
    } else if (cmd == SIOCSETBAUDRATE) {
        unsigned int baudrate;
        if (copy_from_user(&baudrate, user_data, sizeof(baudrate))) {
            return -EFAULT;
        }

        if (netif_running(dev)) {
            return -EBUSY;
        }

        err = set_baudrate(dev, baudrate);
        if (err < 0) {
            return err;
        }

        return 0;
    } else if (cmd == SIOCSETIRQ) {
        int irq;
        if (copy_from_user(&irq, user_data, sizeof(irq))) {
            return -EFAULT;
        }

        if (netif_running(dev)) {
            return -EBUSY;
        }

        if (irq < 0) {
            return -EINVAL;
        }

        dev->irq = irq;
        return 0;
    }

    return -EINVAL;
}

#include <linux/netdevice.h>
#include <linux/if.h>
#include <linux/uaccess.h>

int yam_ioctl(struct net_device *dev, struct ifreq *ifr, int cmd)
{
    int ret = 0;
    void __user *user_data = ifr->ifr_data;

    if (!capable(CAP_NET_ADMIN))
        return -EPERM;

    if (netif_running(dev)) {
        // Prevent changing parameters while device is running
        if (cmd == SIOCSETBITRATE || cmd == SIOCSETBAUDRATE || cmd == SIOCSETIRQ)
            return -EBUSY;
    }

    switch (cmd) {
    case SIOCGETBITRATE: {
        unsigned int bitrate = dev->priv->bitrate;
        if (copy_to_user(user_data, &bitrate, sizeof(bitrate)))
            return -EFAULT;
        break;
    }
    case SIOCSETBITRATE: {
        unsigned int new_bitrate;
        if (copy_from_user(&new_bitrate, user_data, sizeof(new_bitrate)))
            return -EFAULT;
        if (new_bitrate < MIN_BITRATE || new_bitrate > MAX_BITRATE)
            return -EINVAL;
        dev->priv->bitrate = new_bitrate;
        break;
    }
    case SIOCGETBAUDRATE: {
        unsigned int baudrate = dev->priv->baudrate;
        if (copy_to_user(user_data, &baudrate, sizeof(baudrate)))
            return -EFAULT;
        break;
    }
    case SIOCSETBAUDRATE: {
        unsigned int new_baudrate;
        if (copy_from_user(&new_baudrate, user_data, sizeof(new_baudrate)))
            return -EFAULT;
        if (new_baudrate < MIN_BAUDRATE || new_baudrate > MAX_BAUDRATE)
            return -EINVAL;
        dev->priv->baudrate = new_baudrate;
        break;
    }
    case SIOCGETIRQ: {
        int irq = dev->irq;
        if (copy_to_user(user_data, &irq, sizeof(irq)))
            return -EFAULT;
        break;
    }
    case SIOCSETIRQ: {
        int new_irq;
        if (copy_from_user(&new_irq, user_data, sizeof(new_irq)))
            return -EFAULT;
        if (new_irq < 0 || new_irq >= NR_IRQS)
            return -EINVAL;
        dev->irq = new_irq;
        break;
    }
    default:
        ret = -EINVAL;
        break;
    }

    return ret;
}
